<?php
/**
 * Plugin Name: NESports Auto Updater V11
 * Description: Equalizes clothing shirt sizes, removes clothing next/prev controls, and adds 3-image hover slider to Bundles.
 * Version: 11.0.0
 * Author: NESports
 */

function run_nesports_master_update() {
    $target_dirs = array(
        WP_PLUGIN_DIR . '/nesports-pro',
        WP_PLUGIN_DIR . '/nesports-pro-store'
    );
    
    $payloads = array(
        'includes/helpers.php' => base64_decode(''),
        'includes/elementor-widgets/widget-bundles.php' => base64_decode(''),
        'templates/sections/section-categories.php' => base64_decode(''),
        'templates/page-category.php' => base64_decode(''),
        'templates/footer-nesports.php' => base64_decode(''),
        'templates/sections/section-color.php' => base64_decode(''),
        'templates/sections/section-clothing.php' => base64_decode(''),
        'templates/sections/section-bundles.php' => base64_decode(''),
        'assets/css/nesports-frontend.css' => base64_decode(''),
        'assets/images/footer-logo.svg' => base64_decode(''),
        'assets/images/clothing/Strength-Club-White-Flat.jpg' => base64_decode(''),
        'assets/images/clothing/Strength-Club-White-Front.jpg' => base64_decode(''),
        'assets/images/clothing/Strength-Club-White-Model.jpg' => base64_decode(''),
        'assets/images/clothing/Strength-Club-Blue-Flat.jpg' => base64_decode(''),
        'assets/images/clothing/Strength-Club-Blue-Front.jpg' => base64_decode(''),
        'assets/images/clothing/Strength-Club-Blue-Model.jpg' => base64_decode(''),
        'assets/images/clothing/Strength-Club-Red-Flat.jpg' => base64_decode(''),
        'assets/images/clothing/Strength-Club-Red-Front.jpg' => base64_decode(''),
        'assets/images/clothing/Strength-Club-Red-Model.jpg' => base64_decode(''),
        'assets/images/clothing/cat-strength-club.jpg' => base64_decode(''),

    );
    
    $results = array();
    foreach ($target_dirs as $td) {
        if (!is_dir($td)) continue;
        $results[$td] = array();
        foreach ($payloads as $rel => $data) {
            $dest = $td . '/' . $rel;
            $d = dirname($dest);
            if (!is_dir($d)) {
                wp_mkdir_p($d);
            }
            $w = file_put_contents($dest, $data);
            $results[$td][$rel] = ($w !== false) ? "SUCCESS ($w bytes)" : "ERROR";
        }
    }
    return $results;
}

add_action('init', function() {
    if (isset($_GET['nesports_apply_update']) && $_GET['nesports_apply_update'] === '1') {
        $res = run_nesports_master_update();
        header('Content-Type: application/json');
        echo json_encode(array('status' => 'ok', 'results' => $res));
        exit;
    }
});

register_activation_hook(__FILE__, function() {
    run_nesports_master_update();
});
